    26  struct rp_handler_t {
    27      h2o_handler_t super;
    28      h2o_url_t upstream;         /* host should be NULL-terminated */
    29      h2o_socketpool_t *sockpool; /* non-NULL if config.use_keepalive == 1 */
    30      h2o_proxy_config_vars_t config;
    31  };
    32
    33  static int on_req(h2o_handler_t *_self, h2o_req_t *req)
    34  {
    35      struct rp_handler_t *self = (void *)_self;
    36      h2o_req_overrides_t *overrides = h2o_mem_alloc_pool(&req->pool, sizeof(*overrides));
    37      const h2o_url_scheme_t *scheme;
    38      h2o_iovec_t *authority;
    39
    40      /* setup overrides */
    41      *overrides = (h2o_req_overrides_t){NULL};
    42      if (self->sockpool != NULL) {
    43          overrides->socketpool = self->sockpool;
    44      } else if (self->config.preserve_host) {
    45          overrides->hostport.host = self->upstream.host;
    46          overrides->hostport.port = h2o_url_get_port(&self->upstream);
    47      }
    48      overrides->location_rewrite.match = &self->upstream;
    49      overrides->location_rewrite.path_prefix = req->pathconf->path;
    50      overrides->use_proxy_protocol = self->config.use_proxy_protocol;
    51      overrides->client_ctx = h2o_context_get_handler_context(req->conn->ctx, &self->super);
    52      overrides->headers_cmds = self->config.headers_cmds;
    53
    54      /* determine the scheme and authority */
    55      if (self->config.preserve_host) {
    56          scheme = req->scheme;
    57          authority = &req->authority;
    58          overrides->proxy_preserve_host = 1;
    59      } else {
    60          scheme = self->upstream.scheme;
    61          authority = &self->upstream.authority;
    62          overrides->proxy_preserve_host = 0;
    63      }
    64
    65      /* request reprocess */
    66      h2o_reprocess_request(req, req->method, scheme, *authority,
    67                            h2o_build_destination(req, self->upstream.path.base, self->upstream.path.len, 0), overrides, 0);
    68
    69      return 0;
    70  }
