    72  static void on_context_init(h2o_handler_t *_self, h2o_context_t *ctx)
    73  {
    74      struct rp_handler_t *self = (void *)_self;
    75
    76      /* use the loop of first context for handling socketpool timeouts */
    77      if (self->sockpool != NULL && self->sockpool->timeout == UINT64_MAX)
    78          h2o_socketpool_set_timeout(self->sockpool, ctx->loop, self->config.keepalive_timeout);
    79
    80      /* setup a specific client context only if we need to */
    81      if (ctx->globalconf->proxy.io_timeout == self->config.io_timeout && !self->config.websocket.enabled &&
    82          self->config.ssl_ctx == ctx->globalconf->proxy.ssl_ctx)
    83          return;
    84
    85      h2o_http1client_ctx_t *client_ctx = h2o_mem_alloc(sizeof(*ctx));
    86      client_ctx->loop = ctx->loop;
    87      client_ctx->getaddr_receiver = &ctx->receivers.hostinfo_getaddr;
    88      if (ctx->globalconf->proxy.io_timeout == self->config.io_timeout) {
    89          client_ctx->io_timeout = &ctx->proxy.io_timeout;
    90      } else {
    91          client_ctx->io_timeout = h2o_mem_alloc(sizeof(*client_ctx->io_timeout));
    92          h2o_timeout_init(client_ctx->loop, client_ctx->io_timeout, self->config.io_timeout);
    93      }
    94      if (self->config.websocket.enabled) {
    95          /* FIXME avoid creating h2o_timeout_t for every path-level context in case the timeout values are the same */
    96          client_ctx->websocket_timeout = h2o_mem_alloc(sizeof(*client_ctx->websocket_timeout));
    97          h2o_timeout_init(client_ctx->loop, client_ctx->websocket_timeout, self->config.websocket.timeout);
    98      } else {
    99          client_ctx->websocket_timeout = NULL;
   100      }
   101      client_ctx->ssl_ctx = self->config.ssl_ctx;
   102
   103      h2o_context_set_handler_context(ctx, &self->super, client_ctx);
   104  }
