   106  static void on_context_dispose(h2o_handler_t *_self, h2o_context_t *ctx)
   107  {
   108      struct rp_handler_t *self = (void *)_self;
   109      h2o_http1client_ctx_t *client_ctx = h2o_context_get_handler_context(ctx, &self->super);
   110
   111      if (client_ctx == NULL)
   112          return;
   113
   114      if (client_ctx->io_timeout != &ctx->proxy.io_timeout) {
   115          h2o_timeout_dispose(client_ctx->loop, client_ctx->io_timeout);
   116          free(client_ctx->io_timeout);
   117      }
   118      if (client_ctx->websocket_timeout != NULL) {
   119          h2o_timeout_dispose(client_ctx->loop, client_ctx->websocket_timeout);
   120          free(client_ctx->websocket_timeout);
   121      }
   122      free(client_ctx);
   123  }
   124
   125  static void on_handler_dispose(h2o_handler_t *_self)
   126  {
   127      struct rp_handler_t *self = (void *)_self;
   128
   129      if (self->config.ssl_ctx != NULL)
   130          SSL_CTX_free(self->config.ssl_ctx);
   131      free(self->upstream.host.base);
   132      free(self->upstream.path.base);
   133      if (self->sockpool != NULL) {
   134          h2o_socketpool_dispose(self->sockpool);
   135          free(self->sockpool);
   136      }
   137  }
