   139  void h2o_proxy_register_reverse_proxy(h2o_pathconf_t *pathconf, h2o_url_t *upstreams, size_t count, h2o_proxy_config_vars_t *config)
   140  {
   141      struct sockaddr_un sa;
   142      const char *to_sa_err;
   143      struct rp_handler_t *self = (void *)h2o_create_handler(pathconf, sizeof(*self));
   144      self->super.on_context_init = on_context_init;
   145      self->super.on_context_dispose = on_context_dispose;
   146      self->super.dispose = on_handler_dispose;
   147      self->super.on_req = on_req;
   148      self->super.has_body_stream = 1;
   149      if (config->keepalive_timeout != 0) {
   150          size_t i;
   151          int is_ssl;
   152          h2o_socketpool_target_vector_t targets = {};
   153          h2o_vector_reserve(NULL, &targets, count);
   154          self->sockpool = h2o_mem_alloc(sizeof(*self->sockpool));
   155          for (i = 0; i != count; ++i) {
   156              if (config->registered_as_backends && config->reverse_path.base != NULL) {
   157                  upstreams[i].path = config->reverse_path;
   158              }
   159              to_sa_err = h2o_url_host_to_sun(upstreams[i].host, &sa);
   160              is_ssl = upstreams[i].scheme == &H2O_URL_SCHEME_HTTPS;
   161              if (to_sa_err == h2o_url_host_to_sun_err_is_not_unix_socket) {
   162                  h2o_socketpool_init_target_by_hostport(&targets.entries[i], upstreams[i].host, h2o_url_get_port(&upstreams[i]), is_ssl, &upstreams[i]);
   163              } else {
   164                  assert(to_sa_err == NULL);
   165                  h2o_socketpool_init_target_by_address(&targets.entries[i], (void *)&sa, sizeof(sa), is_ssl, &upstreams[i]);
   166              }
   167              targets.size++;
   168          }
   169          h2o_socketpool_init_by_targets(self->sockpool, targets, SIZE_MAX /* FIXME */);
   170      }
   171      to_sa_err = h2o_url_host_to_sun(upstreams[0].host, &sa);
   172      h2o_url_copy(NULL, &self->upstream, &upstreams[0]);
   173      if (to_sa_err) {
   174          h2o_strtolower(self->upstream.host.base, self->upstream.host.len);
   175      }
   176      self->config = *config;
   177      if (self->config.ssl_ctx != NULL)
   178          SSL_CTX_up_ref(self->config.ssl_ctx);
   179  }

